  -- row layer's instance count of the setting (9 on a setting without the clones).
  function UTIL_PPC.Rows()
    local ok, n = pcall(funcLuaMenuCommand, 1175615627, UTIL_PPC.ITEM)
    if ok and type(n) == "number" and n >= 1 then
      return math.min(n, 9)
