    -- v4: the plate row's icon block (evt_pc_row quads, passive_config_build.py ROW_QUADS): dark rounded square
    -- (teambuff_base01, or teambuff_base02 with a badge, as retail SwapPassiveSkillEffectIcon), effect icon on it,
    -- archetype badge (soccer11_20 atlas, as the plate) on its lower right corner
    local icon = e.icon ~= nil and e.icon ~= 0
    local build = e.build ~= nil and e.build >= 0 and type(GeTeamBuffBuildTypeIconTextureName) == "function"
    UTIL_PCI.RowBacking(L, k, icon, build, e.special)
    funcLuaMenuCommand(3405944500, L, 2164615260, icon, k)
    if icon then
      pcall(funcLuaMenuCommand, 558735651, L, 2301895383, e.icon, 566439826, 0, k)
    end
    funcLuaMenuCommand(3405944500, L, 2384755812, build, k)
    if build then
      pcall(funcLuaMenuCommand, 558735651, L, UTIL_PCI.PLATE_TEX, GeTeamBuffBuildTypeIconTextureName(e.build), 669321680, 0, k)
    end
    funcLuaMenuCommand(3405944500, L, 2309656400, e.current == true, k)
    funcLuaMenuCommand(2158717427, L, 442049775, false, k)
    funcLuaMenuCommand(2158717427, L, 3426045766, false, k)
    funcLuaMenuCommand(1233047821, L, k, 3334923667, false)
    funcLuaMenuCommand(1233047821, L, k, 3974820126, false)
  end

  -- filter header above the list: «Z ‹ <category> › C» (shown with the list, its text follows the category)
  function UTIL_PPC.Filter(show, cat)
    local L = UTIL_PPC.FILTER
    if show then
      pcall(UTIL_PPC.Open, L)
      for _, m in ipairs(UTIL_PPC.FILTER_OFF) do
        pcall(funcLuaMenuCommand, 3405944500, L, m, false, 0)
      end
      pcall(funcLuaMenuCommand, 2333948100 --[[text style]], UTIL_PPC.LIST, 0, UTIL_PPC.N_CAT, UTIL_PPC.CAT_STYLE)
      pcall(funcLuaMenuCommand, 1083631230, UTIL_PPC.LIST, UTIL_PPC.N_CAT, UTIL_PPC.Text(UTIL_PPC.CatText(cat or 0)), 0)
    end
    pcall(funcLuaMenuCommand, 711242136, L, 0, show)
    pcall(funcLuaMenuCommand, 3405944500, UTIL_PPC.LIST, UTIL_PPC.N_CAT, show, 0)
  end

  function UTIL_PPC.ListShow(show, list, first, sel)
    if not show then
      UTIL_PPC.Filter(false)
    end
    funcLuaMenuCommand(711242136, UTIL_PPC.BG, 0, show)
    if show then
      pcall(funcLuaMenuCommand, 558735651, UTIL_PPC.BG, 2311471971, 515167937, 3512665951, 0, 0)
    end
    UTIL_PPC.Open(UTIL_PPC.LIST)
    funcLuaMenuCommand(711242136, UTIL_PPC.LIST, 0, show)
    for k = 0, UTIL_PPC.VIEW - 1 do
      local e = show and list[first + k + 1] or nil
      UTIL_PPC.Open(UTIL_PPC.ITEM, k)
      if e ~= nil then
        pcall(UTIL_PPC.ListRow, k, e, first + k == sel)
      end
      funcLuaMenuCommand(711242136, UTIL_PPC.ITEM, k, e ~= nil)
    end
  end

  -- the focused passive on the plate row being edited (retail row look: icon, full description, archetype icons)
  function UTIL_PPC.Preview(slot, e)
    if type(UpdatePassiveSkillLayerInfo) ~= "function" then
      return
    end
    if e == nil then
      pcall(UpdatePassiveLayer, UTIL_PPC.ROWS, slot)
    elseif e.clear then
      pcall(UpdatePassiveSkillLayerInfo, UTIL_PPC.ROWS, slot, UTIL_PPC.h, slot, nil, nil, true, true)
    else
      pcall(UpdatePassiveSkillLayerInfo, UTIL_PPC.ROWS, 0, e.hdl, slot, nil, nil, true, false)
    end
  end

  -- the category and its Z / C keys are in the filter header (UTIL_PPC.Filter)
  function UTIL_PPC.ListGuide(cat)
    UTIL_PPC.Guide({{UTIL_PPC.TX_ELEGIR, UTIL_PPC.GL_ENTER, UTIL_PPC.K_ENTER},
      {UTIL_PPC.TX_BACK, UTIL_PPC.GL_BACK, UTIL_PPC.K_BACK}})
  end

  -- ---- pointer (mouse / VR free cursor; docs/game/ui/mouse-support.md §5, EVT_PointerNew) ----------------------
  -- 2026-10-14 (owner screenshot: hovering a passive row with the green virtual-mouse arrow did not move the cyan
  -- frame). The plate rows and the list rows are drawn by this file with no engine zones of their own (the plate's
  -- rows may also be moved by a plate page mod through the instance position), so the hit test is done here, from
  -- the instances' global positions (4002164178, y up), read at hit-test time:
  --   plate rows (soccer11_20_formation_team_passive, instances 0..4): the 828 x 92 card centred on the instance
  --     origin (_passive_base01 at (-414, 46) in layer units), only on shown rows;
  --   list rows (util_pc_row k): x -98 .. +872 from the row origin, ROW_H 104 centred on it (passive_config_build.py
  --     edit_row), only on rows showing an entry; the filter header's «Z ‹» / «› C» (filter layer local x 120..215 /
  --     563..653, top -172, 56 high); a 40 px band above the first / below the last row while the list scrolls that way.
  -- Hover = that row focused (the d-pad's look, sound, guide / preview); click = Accept on it; wheel / band = scroll
  -- one row; a click on nothing does nothing; Enter / A / the click command belong to the pointer while P.Owns().
  -- EVT_PointerNew(): a pointer helper for menus that draw their own selectable items (docs/game/ui/mouse-support.md §5).
  -- Mouse and VR's free cursor (the stick-driven «virtual mouse», CMND_SET_ENABLE_FREE_CURSOR_FOR_VIRTUAL_MOUSE) are
  -- the same pointer: the engine's pointer position (558229292, screen px, y down) is read every frame and any change
  -- (or the engine's «mouse moved», 3272825600) puts the menu in pointer mode; a menu arrow (CMD_UP/DOWN/LEFT/RIGHT)
  -- ends it. The menu declares its zones each time it draws, from the same positions it draws with:
  --   P.Begin()                              forget the zones of the last drawing
  --   P.Rect(x, y, w, h, id[, edge])         top-left + size, screen px (y down)
  --   P.Box(cx, cy, hw, hh, id[, edge])      centre + half sizes, screen px (y down)
  --   P.Inst(layer, idx, hw, hh, id[, edge]) around a layer instance's global position (read at hit-test time)
  --   (edge = -1 / 1: a scroll band; hovering it scrolls every P.REPEAT frames: ev.edge)
  -- The last zone declared wins (popups / buttons drawn over cards). Per frame (Step): local ev = P.Poll() with
  --   ev.moved   the pointer moved (pointer mode on)          ev.hot / ev.changed  zone id under the pointer / it changed
  --   ev.click   id clicked (mouse left button, or Accept / the free cursor's A in pointer mode) on a zone
  --   ev.miss    a mouse click on no zone (do nothing; Enter / A there = the menu's key Accept, pointer mode off)
  --   ev.wheel   -1 up / 1 down (CMD_EVT_WHEEL_*)
  --   ev.edge    -1 / 1 from a scroll band                     ev.keys   a menu arrow was pressed (pointer mode off)
  --   ev.hover   the zone under the pointer, only on a frame the pointer MOVED (or was clicked): hover by movement only,
  --              so a redraw / scroll / camera move under a resting pointer never re-selects (retail behaviour)
  -- P.KeyStep(): the menu moved its selection itself (its own key callbacks, a polled stick / D-pad the arrows above do
  -- not see): pointer mode off and the resting position taken as the baseline, so the pad owns the selection until the
  -- pointer really moves again or clicks (2026-10-13, contact map: a resting mouse pinned the selection under it).
  -- Hover = move the selection to ev.hot with the keyboard highlight; ev.click = select it and decide. The menu's own
  -- Accept callbacks (OnEnter / OnDecideFocus / a polled CMD_ENTER) return early while P.Owns(): in pointer mode the
  -- click belongs to the pointer, so an item not under it is never activated. Zones are only declared for pickable,
  -- shown items (never hidden ones). P.Forget() after a redraw under a still pointer re-focuses the zone beneath it.
  EVT_PointerNew = EVT_PointerNew or function()
    local P = {zones = {}, on = false, x = nil, y = nil, hot = nil, prev = {}, edge_t = 0, REPEAT = 10}
    local MOVED, POS, GPOS, CHECK, CTRL = 3272825600, 558229292, 4002164178, 4265778440, 1332654303
    local LEFT, CLICK = 218912913 --[[CMD_EVT_MOUSE_LEFT]], 1651523701 --[[CMD_ENTER_CLICK]]
    local W_UP, W_DOWN = 1942756954 --[[CMD_EVT_WHEEL_UP]], 1623431741 --[[CMD_EVT_WHEEL_DOWN]]
    local NAV = {1197218715, 3259546669, 2765147006, 2075023265} -- CMD_UP / DOWN / LEFT / RIGHT
    local CTRLS = {CTRL, 2748927068 --[[analog-move control: the stick's menu moves]]}
    local function M(cmd, ...)
      local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
      if ok then return a, b end
      return nil
    end
    local function In(cmd, ctrl)
      local ok, r = pcall(funcLuaCommand, CHECK, ctrl or CTRL, cmd)
      return ok and r == true
    end
    local function Edge(cmd, ctrl)
      local key = ctrl and (tostring(ctrl) .. ":" .. tostring(cmd)) or cmd
      local now = In(cmd, ctrl)
      local was = P.prev[key]
      P.prev[key] = now
      return now and not was
    end
    function P.Begin()
      P.zones = {}
    end
    function P.Rect(x, y, w, h, id, edge)
      P.zones[#P.zones + 1] = {x, y, x + w, y + h, id = id, edge = edge}
    end
    function P.Box(cx, cy, hw, hh, id, edge)
      P.zones[#P.zones + 1] = {cx - hw, cy - hh, cx + hw, cy + hh, id = id, edge = edge}
    end
    function P.Inst(layer, idx, hw, hh, id, edge)
      P.zones[#P.zones + 1] = {layer = layer, idx = idx, hw = hw, hh = hh, id = id, edge = edge}
    end
    function P.Pos()
      local x, y = M(POS)
      if type(x) == "number" and type(y) == "number" then return x, y end
      return nil
    end
    function P.At(x, y)
      if x == nil then x, y = P.x, P.y end
      if x == nil then return nil end
      for i = #P.zones, 1, -1 do
        local z = P.zones[i]
        if z.layer ~= nil then
          local gx, gy = M(GPOS, z.layer, z.idx)
          if type(gx) == "number" and type(gy) == "number" and math.abs(x - gx) <= z.hw and math.abs(-y - gy) <= z.hh then
            return z
          end
        elseif x >= z[1] and x < z[3] and y >= z[2] and y < z[4] then
          return z
        end
      end
      return nil
    end
    -- the Accept being pressed now is a pointer click: the mouse button, or Accept / A in pointer mode ON an item
    -- (Enter / A with the pointer resting on empty space is a key Accept on the current selection)
    function P.Owns()
      return In(LEFT) or (P.on and In(CLICK) and P.At() ~= nil)
    end
    -- forget the hovered zone: the next Poll reports the zone under a still pointer as changed (after a redraw)
    function P.Forget()
      P.hot = nil
    end
    function P.KeyStep()
      P.on, P.hot = false, nil
      local x, y = P.Pos()
      if x ~= nil then P.x, P.y = x, y end
    end
    function P.Reset()
      P.zones, P.on, P.hot, P.prev, P.edge_t = {}, false, nil, {}, 0
      P.x, P.y = P.Pos()
      -- a press / wheel / arrow held from the screen before is no click, no scroll, no key
      for _, c in ipairs({LEFT, CLICK, W_UP, W_DOWN}) do Edge(c) end
      for _, ctrl in ipairs(CTRLS) do
        for _, c in ipairs(NAV) do Edge(c, ctrl) end
      end
    end
    function P.Poll()
      local ev = {}
      local x, y = P.Pos()
      if x ~= nil then
        local moved = M(MOVED) == true
        if not moved and P.x ~= nil and (math.abs(x - P.x) > 1 or math.abs(y - P.y) > 1) then
          moved = true    -- the free cursor (stick) moves the pointer without the mouse's «moved» flag
        end
        P.x, P.y = x, y
        if moved then
          P.on, ev.moved = true, true
        end
      end
      for _, ctrl in ipairs(CTRLS) do
        for _, c in ipairs(NAV) do
          if Edge(c, ctrl) then
            ev.keys = true
          end
        end
      end
      if ev.keys and not ev.moved then
        P.on = false
      end
      local left, click = Edge(LEFT), Edge(CLICK)
      if left then
        P.on = true
      end
      local z = P.on and P.At() or nil
      local id = z and z.id or nil
      ev.changed = id ~= P.hot
      P.hot, ev.hot = id, id
      if z ~= nil and (ev.moved or left) then
        ev.hover = id
      end
      if left then
        if z ~= nil then
          ev.click = id
        else
          ev.miss = true                 -- a mouse click on empty space: nothing
        end
      elseif click and P.on then
        if z ~= nil then
          ev.click = id
        else
          P.on, P.hot = false, nil       -- Enter / A on empty space: the menu's key Accept takes it (selection kept)
        end
      end
      if In(W_DOWN) then
        ev.wheel = 1
      elseif In(W_UP) then
        ev.wheel = -1
      end
      if z ~= nil and z.edge ~= nil then
        P.edge_t = P.edge_t - 1
        if P.edge_t <= 0 then
          ev.edge, P.edge_t = z.edge, P.REPEAT
        end
      else
        P.edge_t = 0
      end
      return ev
    end
    return P
  end
  UTIL_PPC.LAYER_GLOBAL_POS = 4002164178
  UTIL_PPC.PLATE_ROW_HALF_W, UTIL_PPC.PLATE_ROW_HALF_H = 414, 46
  UTIL_PPC.LIST_ROW_X, UTIL_PPC.LIST_ROW_W, UTIL_PPC.LIST_ROW_H = -98, 970, 104
  UTIL_PPC.CAT_LEFT, UTIL_PPC.CAT_RIGHT, UTIL_PPC.CAT_TOP, UTIL_PPC.CAT_H = {120, 95}, {563, 90}, -172, 56
  UTIL_PPC.SCROLL_BAND_H = 40
  UTIL_PPC.FOCUS_LOG_MAX = 200

  function UTIL_PPC.GlobalPos(L, k)
    local ok, x, y = pcall(funcLuaMenuCommand, UTIL_PPC.LAYER_GLOBAL_POS, L, k)
    if ok and type(x) == "number" and type(y) == "number" then
      return x, y
    end
    return nil
  end

  -- one line per focus change (first runs: which row, by mouse or pad)
  function UTIL_PPC.LogFocus(where, row, by)
    UTIL_PPC.focus_logs = (UTIL_PPC.focus_logs or 0) + 1
    if UTIL_PPC.focus_logs <= UTIL_PPC.FOCUS_LOG_MAX then
      UTIL_PPC.Log("focus", where, "row", row, "by", by)
    end
  end

  function UTIL_PPC.PlateRowShown(i)
    local L = UTIL_PPC.ROWS
    return funcLuaMenuCommand(262659071, L) == true and funcLuaMenuCommand(2640875187, L, i) == true
      and funcLuaMenuCommand(1262717583 --[[CMND_IS_LAYER_VISIBLE]], L, i) == true
  end

  -- the session's zones: the 5 plate rows (id = row index)
  function UTIL_PPC.PlateRowZones(P)
    P.Begin()
    for i = 0, 4 do
      if UTIL_PPC.PlateRowShown(i) then
        P.Inst(UTIL_PPC.ROWS, i, UTIL_PPC.PLATE_ROW_HALF_W, UTIL_PPC.PLATE_ROW_HALF_H, i)
        if not UTIL_PPC.zones_logged then
          local x, y = UTIL_PPC.GlobalPos(UTIL_PPC.ROWS, i)
          UTIL_PPC.Log("pointer zone plate row", i, "centre", tostring(x), tostring(y and -y))
        end
      end
    end
    UTIL_PPC.zones_logged = true
  end

  -- the picker's zones: list rows (id = view index k), category arrows, scroll bands
  function UTIL_PPC.ListZones(P, list, first)
    P.Begin()
    local fx, fy = UTIL_PPC.GlobalPos(UTIL_PPC.FILTER, 0)
    if fx ~= nil then
      P.Rect(fx + UTIL_PPC.CAT_LEFT[1], -(fy + UTIL_PPC.CAT_TOP), UTIL_PPC.CAT_LEFT[2], UTIL_PPC.CAT_H, "cat_left")
      P.Rect(fx + UTIL_PPC.CAT_RIGHT[1], -(fy + UTIL_PPC.CAT_TOP), UTIL_PPC.CAT_RIGHT[2], UTIL_PPC.CAT_H, "cat_right")
    end
    local top, bottom = nil, nil
    for k = 0, UTIL_PPC.VIEW - 1 do
      if list[first + k + 1] ~= nil then
        local x, y = UTIL_PPC.GlobalPos(UTIL_PPC.ITEM, k)
        if x ~= nil then
          local sy = -y - UTIL_PPC.LIST_ROW_H / 2
          P.Rect(x + UTIL_PPC.LIST_ROW_X, sy, UTIL_PPC.LIST_ROW_W, UTIL_PPC.LIST_ROW_H, k)
          top = top or {x + UTIL_PPC.LIST_ROW_X, sy}
          bottom = {x + UTIL_PPC.LIST_ROW_X, sy + UTIL_PPC.LIST_ROW_H}
        end
      end
    end
    if top ~= nil and first > 0 then
      P.Rect(top[1], top[2] - UTIL_PPC.SCROLL_BAND_H, UTIL_PPC.LIST_ROW_W, UTIL_PPC.SCROLL_BAND_H, "scroll_up", -1)
    end
    if bottom ~= nil and first + UTIL_PPC.VIEW < #list then
      P.Rect(bottom[1], bottom[2], UTIL_PPC.LIST_ROW_W, UTIL_PPC.SCROLL_BAND_H, "scroll_down", 1)
    end
  end

  -- one pointer per session (UTIL_PPC.pointer), reset whenever the screen under it changes (a held press is no click)
  function UTIL_PPC.Pointer()
    if UTIL_PPC.pointer == nil and type(EVT_PointerNew) == "function" then
      local ok, P = pcall(EVT_PointerNew)
      if ok then
        UTIL_PPC.pointer = P
      end
    end
    return UTIL_PPC.pointer
  end

  function UTIL_PPC.PointerReset()
    local P = UTIL_PPC.Pointer()
    if P ~= nil then
      pcall(P.Reset)
    end
  end

  -- this frame's pointer event with the given zones: ev, owns (the Accept pressed now is the pointer's)
  function UTIL_PPC.PointerPoll(zones, ...)
    local P = UTIL_PPC.Pointer()
    if P == nil or not pcall(zones, P, ...) then
      return {}, false
    end
    local ok, ev = pcall(P.Poll)
    if not ok or type(ev) ~= "table" then
      return {}, false
    end
    local okO, owns = pcall(P.Owns)
    return ev, okO and owns == true
  end

  -- the result of a set request: sound, header, message
  function UTIL_PPC.SetResult(slot, ok, code)
    if ok then
      UTIL_PPC.SE(UTIL_PPC.SE_OK)
      UTIL_PPC.Header()
      return
    end
    UTIL_PPC.SE(UTIL_PPC.SE_NG)
    UTIL_PPC.Preview(slot, nil)
    if code == 2 then
      UTIL_PPC.Message(UTIL_PPC.TX_LOCKED)
    elseif code == 7 then
      UTIL_PPC.Message(UTIL_PPC.TX_LIMIT)
    elseif code == 4 then
      UTIL_PPC.Message(UTIL_PPC.TX_DUP)
    else
      UTIL_PPC.Message(UTIL_PPC.TX_FAIL)
    end
  end

  -- the picker on row `slot`; returns after a choice or Atrás (the original's loop)
  function UTIL_PPC.Pick(slot)
    UTIL_PPC.VIEW = UTIL_PPC.Rows()
    local cat = 0
    local list, init
    list, cat, init = UTIL_PPC.Build(slot, cat)
    if #list == 0 and UTIL_PPC.Kind(slot) == 1 then
      -- a special slot (declared slot rules) with no special for this player: one row saying so
      local none = UTIL_PPC.Text(UTIL_PPC.TX_SPECIAL_NONE)
      list = {{idx = -1, none = true, text = none, icon = 0, build = -1, special = true}}
      init = 0
    end
    if #list == 0 then
      UTIL_PPC.SE(UTIL_PPC.SE_NG)
      return
    end
    local sel = init
    local first = math.max(0, math.min(sel, #list - UTIL_PPC.VIEW))
    UTIL_PPC.Mark(-1)
    UTIL_PPC.ListShow(true, list, first, sel)
    UTIL_PPC.Filter(true, cat)
    UTIL_PPC.Preview(slot, list[sel + 1])
    UTIL_PPC.ListGuide(cat)
    coroutine.yield()
    local chosen = nil
    UTIL_PPC.PointerReset()
    while true do
      coroutine.yield()
      local moved = false
      local by = "pad"
      local cat_dir = nil
      local ev, owns = UTIL_PPC.PointerPoll(UTIL_PPC.ListZones, list, first)
      local clicked = ev.click
      local scroll = ev.wheel or ev.edge
      if UTIL_PPC.Key(UTIL_PPC.K_BACK) then
        UTIL_PPC.SE(UTIL_PPC.SE_BACK)
        break
      elseif type(clicked) == "number" or (not owns and (UTIL_PPC.Key(UTIL_PPC.K_ENTER) or UTIL_PPC.Key(UTIL_PPC.K_CLICK))) then
        if type(clicked) == "number" and list[first + clicked + 1] ~= nil then
          sel = first + clicked
          UTIL_PPC.LogFocus("list", sel, "mouse click")
        end
        chosen = list[sel + 1]
        break
      elseif clicked == "cat_left" or clicked == "cat_right" then
        cat_dir = clicked == "cat_left" and -1 or 1
        by = "mouse"
      elseif type(ev.hover) == "number" and list[first + ev.hover + 1] ~= nil and first + ev.hover ~= sel then
        sel = first + ev.hover
        moved = true
        by = "mouse"
      elseif scroll ~= nil then
        -- wheel / scroll band: the view one row; the focus stays under the pointer (else inside the view)
        local first2 = math.max(0, math.min(first + scroll, #list - UTIL_PPC.VIEW))
        if first2 ~= first then
          first = first2
          if type(ev.hot) == "number" and list[first + ev.hot + 1] ~= nil then
            sel = first + ev.hot
          else
            sel = math.max(first, math.min(sel, first + UTIL_PPC.VIEW - 1))
          end
          moved = true
          by = "mouse"
        end
      elseif UTIL_PPC.Key(UTIL_PPC.K_DOWN) and sel < #list - 1 then
        sel = sel + 1
        if sel >= first + UTIL_PPC.VIEW then
          first = first + 1
        end
        moved = true
      elseif UTIL_PPC.Key(UTIL_PPC.K_UP) and sel > 0 then
        sel = sel - 1
        if sel < first then
          first = first - 1
        end
        moved = true
      elseif UTIL_PPC.Key(UTIL_PPC.K_L1) or UTIL_PPC.Key(UTIL_PPC.K_R1) then
        cat_dir = UTIL_PPC.Key(UTIL_PPC.K_L1) and -1 or 1
      end
      if cat_dir ~= nil then
        local dir = cat_dir
        local ok, c = pcall(funcLuaCommand, UTIL_PPC.CMD_CAT_NEXT, UTIL_PPC.h, slot, cat, dir)
        if ok and type(c) == "number" and c ~= cat then
          local l2, c2 = UTIL_PPC.Build(slot, c)
          if #l2 > 0 then
            list, cat = l2, c2
            sel = 0
            for k, e in ipairs(list) do
              if e.current then
                sel = k - 1
              end
            end
            first = math.max(0, math.min(sel, #list - UTIL_PPC.VIEW))
            UTIL_PPC.Filter(true, cat)
            moved = true
          end
        end
      end
      if moved then
        UTIL_PPC.SE(UTIL_PPC.SE_MOVE)
        UTIL_PPC.ListShow(true, list, first, sel)
        UTIL_PPC.Preview(slot, list[sel + 1])
        UTIL_PPC.LogFocus("list", sel, by)
      end
    end
    UTIL_PPC.ListShow(false, list, first, sel)
    if chosen ~= nil and not chosen.none then
      local id = 0
      if not chosen.clear then
        id = funcLuaCommand(UTIL_PPC.CMD_LIST_ID, chosen.idx)
      end
      local ok, code = funcLuaCommand(UTIL_PPC.CMD_SET, UTIL_PPC.h, slot, id)
      UTIL_PPC.Log("set", UTIL_PPC.h, slot, id, ok, code)
      UTIL_PPC.SetResult(slot, ok, code)
    else
      UTIL_PPC.Preview(slot, nil)
    end
    coroutine.yield()
  end

  -- the session (the original's loop): a cursor on the 5 rows
  function UTIL_PPC.Session(h)
    local ok, got, mode, _, _, max_slots, inactive = pcall(funcLuaCommand, UTIL_PPC.CMD_INFO, h)
    if not ok or got ~= true or type(mode) ~= "number" or mode <= 0 then
      return
    end
    UTIL_PPC.h, UTIL_PPC.mode = h, mode
    UTIL_PPC.max_slots = type(max_slots) == "number" and max_slots or 5
    UTIL_PPC.Log("session", h, "mode", mode, "max_slots", UTIL_PPC.max_slots, "inactive", inactive)
    if type(UpdatePersonalPlatePage) == "function" then
      pcall(UpdatePersonalPlatePage, 2)
    end
    coroutine.yield()
    UTIL_PPC.DrawRows()
    if type(inactive) == "number" and inactive > 0 then
      -- stored choices the current rules do not apply (more than max_slots, or of the wrong kind): kept, grey
      UTIL_PPC.Message(UTIL_PPC.TX_INACTIVE)
    end
    local sel = 0
    while sel < 4 and UTIL_PPC.Locked(sel) do
      sel = sel + 1
    end
    UTIL_PPC.slot = sel
    UTIL_PPC.Mark(sel)
    UTIL_PPC.RowsGuide(sel)
    coroutine.yield()
    UTIL_PPC.zones_logged = false
    UTIL_PPC.PointerReset()
    -- the focus on row `to` (d-pad or pointer): the same frame, sound and guide either way
    local function FocusRow(to, by)
      sel = to
      UTIL_PPC.slot = sel
      UTIL_PPC.SE(UTIL_PPC.SE_MOVE)
      UTIL_PPC.Mark(sel)
      UTIL_PPC.RowsGuide(sel)
      UTIL_PPC.LogFocus("plate", sel, by)
    end
    while true do
      coroutine.yield()
      local ev, owns = UTIL_PPC.PointerPoll(UTIL_PPC.PlateRowZones)
      local clicked = type(ev.click) == "number" and ev.click or nil
      if UTIL_PPC.Key(UTIL_PPC.K_BACK) then
        UTIL_PPC.SE(UTIL_PPC.SE_BACK)
        break
      elseif clicked ~= nil or (not owns and (UTIL_PPC.Key(UTIL_PPC.K_ENTER) or UTIL_PPC.Key(UTIL_PPC.K_CLICK))) then
        if clicked ~= nil and clicked ~= sel then
          sel = clicked
          UTIL_PPC.slot = sel
          UTIL_PPC.Mark(sel)
          UTIL_PPC.LogFocus("plate", sel, "mouse click")
        end
        if UTIL_PPC.Locked(sel) then
          UTIL_PPC.SE(UTIL_PPC.SE_NG)
          UTIL_PPC.Message(UTIL_PPC.LockText(sel))
        else
          UTIL_PPC.SE(UTIL_PPC.SE_OK)
          UTIL_PPC.Pick(sel)
          UTIL_PPC.DrawRows()
          UTIL_PPC.Mark(sel)
        end
        UTIL_PPC.RowsGuide(sel)
        UTIL_PPC.PointerReset()
      elseif type(ev.hover) == "number" and ev.hover ~= sel then
        FocusRow(ev.hover, "mouse")
      elseif UTIL_PPC.Key(UTIL_PPC.K_DOWN) and sel < 4 then
        FocusRow(sel + 1, "pad")
      elseif UTIL_PPC.Key(UTIL_PPC.K_UP) and sel > 0 then
        FocusRow(sel - 1, "pad")
      elseif UTIL_PPC.Key(UTIL_PPC.K_FUNC3) then
        local okS, _, configured, locked, stored = pcall(funcLuaCommand, UTIL_PPC.CMD_SLOT, h, sel)
        -- a configured row, or an inactive stored choice (wrong kind / past the limit): FUNC3 clears it
        if okS and not locked and (configured or (type(stored) == "number" and stored ~= 0)) then
          local okC, code = funcLuaCommand(UTIL_PPC.CMD_SET, h, sel, 0)
          UTIL_PPC.SetResult(sel, okC, code)
          UTIL_PPC.DrawRows()
          UTIL_PPC.Mark(sel)
          UTIL_PPC.RowsGuide(sel)
          UTIL_PPC.PointerReset()
        else
          UTIL_PPC.SE(UTIL_PPC.SE_NG)
        end
      end
    end
    UTIL_PPC.slot = nil
    UTIL_PPC.Mark(-1)
    UTIL_PPC.mode = 0
    UTIL_PPC.DrawRows()
  end

  function UTIL_PPC.Finish()
    UTIL_PPC.co = nil
    UTIL_PPC.pointer = nil
    UTIL_PPC.slot = nil
    pcall(UTIL_PPC.Mark, -1)
    pcall(UTIL_PPC.ListShow, false, {}, 0, 0)
    UTIL_PPC.Log("session end")
    funcLuaCommand(3363400568, UTIL_PPC.KEY_DONE)
    funcLuaCommand(3860611758, UTIL_PPC.KEY_DONE, 0, 1, 1)
  end

  -- every frame: start a requested session, or run the current one
  function UTIL_PPC.Poll()
    UTIL_PPC.HookHeader()
    if UTIL_PPC.co ~= nil then
      local ok, err = coroutine.resume(UTIL_PPC.co)
      if not ok then
        UTIL_PPC.Log("session error", err)
        UTIL_PPC.Finish()
      elseif coroutine.status(UTIL_PPC.co) == "dead" then
        UTIL_PPC.Finish()
      end
      return
    end
    local okH, has = pcall(funcLuaCommand, 2947612279, UTIL_PPC.KEY_REQ)
    if not okH or not has then
      return
    end
    local h = funcLuaCommand(3522198769, UTIL_PPC.KEY_REQ)
    funcLuaCommand(3363400568, UTIL_PPC.KEY_REQ)
    UTIL_PPC.parent = 0
    if funcLuaCommand(2947612279, UTIL_PPC.KEY_PARENT) then
      UTIL_PPC.parent = funcLuaCommand(3522198769, UTIL_PPC.KEY_PARENT)
      funcLuaCommand(3363400568, UTIL_PPC.KEY_PARENT)
    end
    UTIL_PPC.co = coroutine.create(UTIL_PPC.Session)
    local ok, err = coroutine.resume(UTIL_PPC.co, h)
    if not ok then
      UTIL_PPC.Log("session error", err)
      UTIL_PPC.Finish()
    elseif coroutine.status(UTIL_PPC.co) == "dead" then
      UTIL_PPC.Finish()
    end
  end

  UTIL_PPC.Wrap("PostStep", function(prev)
    return function(...)
      local r
      if prev then
        r = prev(...)
      end
      pcall(UTIL_PPC.Poll)
      pcall(UTIL_PPC.Decorate)
      return r
    end
  end, true)

  -- Shared by Utilities' passive configurator (research/grafts/passive_config: team dock + plate) and Inazuma
  -- Fantasy's Supertécnicas screen (research/grafts/ss2_pc_rows): included as @ICONS@, built into each mod's patch.
  -- ---- archetype icons of the status plate header ----------------------------------------------------------------
  -- Retail draws ONE build icon (chara field 36 = the archetype the configurator derives: slot 4's for a dual one) on
  -- _icon_build_dmy01 in the header's left strip (soccer11_04 / soccer11_04pp layouts). A dual archetype (slots 4
  -- and 5 of different archetypes, CMND_UTIL_PC_INFO) also shows slot 5's archetype on _icon_lock_status01: the
  -- 28 px quad right above it in the same strip, centred on it (retail hides that quad on every refresh, so a single
  -- archetype keeps the retail look). Hooked on UpdateCharaStatusPlateInfoByCharaStHdl, which every header refresh
  -- goes through (BySoccerCharaHdl / UseAttributeBg included).
  UTIL_PCI = UTIL_PCI or {}
  UTIL_PCI.CMD_INFO = 3352491761
  UTIL_PCI.ICON_TEX = 2320109963 -- #/menu/200_icon/15_icon_common/icon_common.g4tx
  UTIL_PCI.LOCK_MESH = 1670039012 -- _icon_lock_status01
  UTIL_PCI.LOCK_DUMMY = 3276571178
  UTIL_PCI.LAYERS = UTIL_PCI.LAYERS or {}
  UTIL_PCI.LAYERS[1844915256] = true -- soccer11_04_formation_chara_status (plate, team dock)
  UTIL_PCI.LAYERS[607716004] = true -- soccer11_04_chara_status (Supertécnicas screen)

  -- ---- list picker rows (evt_pc_row, both pickers): the plate row's dark rounded square behind the icon -----------
  UTIL_PCI.PLATE_TEX = 4021797290 -- #/menu/00_soccer/soccer11/soccer11_20/soccer11_20.g4tx
  UTIL_PCI.ROW_BACK_MESH = 2172872396 -- _icon_cmd_type_base01 (72 px backing quad of evt_pc_row)
  UTIL_PCI.ROW_BACK_DUMMY = 1011017977 -- icon_cmd_type_base01
  UTIL_PCI.ROW_MASKED_MESH = 1255155594 -- _icon_cmd_type_dmy01 (unused)
  UTIL_PCI.PLATE_SLOT = 2597149412 -- teambuff_base01 (texture slot of the plate row's _teambuff_base01)
  -- the special passive's tile (soccer11_20 sprite): only when a mod's slot rules declare one ([slots] special_tile,
  -- answered by CMND_UTIL_PC_SPECIAL; the plate session sets it), else the retail tile
  UTIL_PCI.SPECIAL_TILE = UTIL_PCI.SPECIAL_TILE or 0

  -- ---- mods' passive icons ----------------------------------------------------------------------------------------
  -- A mod draws its own icon for a passive effect (sprite of the per-language atlas icon_teambuff) instead of the
  -- retail buff icon of the effect (GRAND_TOTAL_INFO buff icon, kept for the match HUD): its passive_config\*.toml
  -- [[effect_icon]] (Utilities, docs/game/mechanics/pasivas-configurables.md §3), answered by CMND_UTIL_PC_EFF_ICON
  -- (0 = none). Asked once per effect and VM. Wraps the retail SwapPassiveSkillEffectIcon (plate rows, techniques
  -- screen); the pickers ask UTIL_PCI.EffIcon.
  UTIL_PCI.TEAMBUFF_TEX = 2301895383 -- #/menu/200_icon/08_icon_teambuff/<LG>/icon_teambuff.g4tx
  UTIL_PCI.TEAMBUFF_SLOT = 3234721532 -- icon_teambuff_dmy01 (the retail row's buff icon slot)
  UTIL_PCI.CMD_EFF_ICON = 1849460459
  UTIL_PCI.EFF_ICON = UTIL_PCI.EFF_ICON or {}
  function UTIL_PCI.EffIcon(eff)
    if type(eff) ~= "number" or eff == 0 then
      return nil
    end
    local v = UTIL_PCI.EFF_ICON[eff]
    if v == nil then
      local ok, spr = pcall(funcLuaCommand, UTIL_PCI.CMD_EFF_ICON, eff)
      v = (ok and type(spr) == "number") and spr or 0
      UTIL_PCI.EFF_ICON[eff] = v
    end
    return v ~= 0 and v or nil
  end
  function UTIL_PCI.RowEffIcon(L, k, eff)
    local spr = UTIL_PCI.EffIcon(eff)
    if spr ~= nil then
      pcall(funcLuaMenuCommand, 558735651, L, UTIL_PCI.TEAMBUFF_TEX, spr, UTIL_PCI.TEAMBUFF_SLOT, 0, k)
    end
    return spr ~= nil
  end
  -- special = an entry of a special slot: the declared special tile (UTIL_PCI.SPECIAL_TILE, 0 = none)
  function UTIL_PCI.RowBacking(L, k, show, badge, special)
    funcLuaMenuCommand(3405944500, L, UTIL_PCI.ROW_MASKED_MESH, false, k)
    funcLuaMenuCommand(3405944500, L, UTIL_PCI.ROW_BACK_MESH, show == true, k)
    if show then
      local tile = special and UTIL_PCI.SPECIAL_TILE ~= nil and UTIL_PCI.SPECIAL_TILE ~= 0 and UTIL_PCI.SPECIAL_TILE or nil
      pcall(funcLuaMenuCommand, 558735651, L, UTIL_PCI.PLATE_TEX, tile or (badge and 63179614) or 2597149412,
        UTIL_PCI.ROW_BACK_DUMMY, 0, k) -- special tile / teambuff_base02 / teambuff_base01
    end
  end

  function UTIL_PCI.DualIcon(L, idx, h, kind)
    if not UTIL_PCI.LAYERS[L] or type(h) ~= "number" or h == 0 or kind == 6 then
      return
    end
    idx = idx or 0
    if type(GetBuildTypeIconTextureNameByCharaStHdl) == "function" and GetBuildTypeIconTextureNameByCharaStHdl(h) == 0 then
      return
    end
    local ok, got, _, a, b = pcall(funcLuaCommand, UTIL_PCI.CMD_INFO, h)
    if not ok or got ~= true or type(a) ~= "number" or type(b) ~= "number" then
      return
    end
    if a < 0 or a > 5 or b < 0 or b > 5 or a == b or type(GeTeamBuffBuildTypeIconTextureName) ~= "function" then
      return
    end
    local tex = GeTeamBuffBuildTypeIconTextureName(b)
    if tex == nil or tex == 0 then
      return
    end
    funcLuaMenuCommand(558735651, L, UTIL_PCI.ICON_TEX, tex, UTIL_PCI.LOCK_DUMMY, 0, idx)
    funcLuaMenuCommand(3405944500, L, UTIL_PCI.LOCK_MESH, true, idx)
  end

  -- Install(wrap): the wrappers of SwapPassiveSkillEffectIcon (own effect icons on the plate rows) and
  -- UpdateCharaStatusPlateInfoByCharaStHdl (the dual archetype's 2nd icon). wrap(name, make) wraps global `name`
  -- (make(orig) returns the wrapper): Utilities' hook files pass their EVT_Host wrapper; without one (a script no
  -- host owns, e.g. Inazuma Fantasy's Supertécnicas screen) the globals are wrapped directly, once each. Hook() =
  -- Install with the direct wrapper (also once per frame from the plate: a global defined later is caught then).
  UTIL_PCI.done = UTIL_PCI.done or {}
  function UTIL_PCI.DirectWrap(name, make)
    local cur = _ENV[name]
    if type(cur) ~= "function" or UTIL_PCI.done[name] then
      return UTIL_PCI.done[name] == true
    end
    _ENV[name] = make(cur)
    UTIL_PCI.done[name] = true
    return true
  end
  function UTIL_PCI.Install(wrap)
    wrap = wrap or UTIL_PCI.DirectWrap
    if UTIL_PCI.installed == wrap then
      return
    end
    local a = wrap("SwapPassiveSkillEffectIcon", function(prev)
      return function(L, k, eff, ...)
        local r = table.pack(prev(L, k, eff, ...))
        pcall(UTIL_PCI.RowEffIcon, L, k, eff)
        return table.unpack(r, 1, r.n)
      end
    end)
    local b = wrap("UpdateCharaStatusPlateInfoByCharaStHdl", function(prev)
      return function(a1, a2, a3, a4, a5, a6, ...)
        local r1, r2, r3, r4 = prev(a1, a2, a3, a4, a5, a6, ...)
        pcall(UTIL_PCI.DualIcon, a1, a2, a3, a6)
        return r1, r2, r3, r4
      end
    end)
    if a and b then
      UTIL_PCI.installed = wrap
    end
  end
  function UTIL_PCI.Hook()
    if UTIL_PCI.installed == nil then
      UTIL_PCI.Install(UTIL_PCI.DirectWrap)
    end
  end
  UTIL_PCI.Install(UTIL_PPC.Wrap)

  -- redraw the header after a change, as the plate's own OnOpenLayer does (UpdateCharaStatusPlateInfo(n11): the
  -- handle the plate holds, GetPersonalPlateSelectCharaStHdl): retail icon (field 36, derived live) + ours
  function UTIL_PPC.Header()
    if type(UpdateCharaStatusPlateInfo) ~= "function" then
      return
    end
    local h = nil
    if type(GetPersonalPlateSelectCharaStHdl) == "function" then
      local ok, v = pcall(GetPersonalPlateSelectCharaStHdl)
      if ok and type(v) == "number" and v ~= 0 then
        h = v
      end
    end
    h = h or UTIL_PPC.h
    if h ~= nil then
      pcall(UpdateCharaStatusPlateInfo, h)
    end
  end

  function UTIL_PPC.HookHeader()
    UTIL_PCI.Install(UTIL_PPC.Wrap)
  end

  -- the picker layers start hidden, above the team dock
  UTIL_PPC.Wrap("OnSetupLayer", function(prev)
    return function(a1, a2, ...)
      if a1 == UTIL_PPC.BG or a1 == UTIL_PPC.LIST or a1 == UTIL_PPC.ITEM or a1 == UTIL_PPC.FILTER then
        local prio = (a1 == UTIL_PPC.BG and 449) or (a1 == UTIL_PPC.LIST and 450) or (a1 == UTIL_PPC.FILTER and 452) or 451
        funcLuaMenuCommand(1491630496, a1, a2, prio, true)
        if a1 == UTIL_PPC.LIST then
          funcLuaMenuCommand(2158717427, a1, 1839509013, false, a2)
          funcLuaMenuCommand(2158717427, a1, 1060758565, false, a2)
          funcLuaMenuCommand(3405944500, a1, 3660005257, false, a2)
        end
        funcLuaMenuCommand(711242136, a1, a2, false)
        return
      end
      return prev(a1, a2, ...)
    end
  end)
  UTIL_PPC.Wrap("OnOpenLayer", function(prev)
    return function(a1, a2, ...)
      if a1 == UTIL_PPC.BG or a1 == UTIL_PPC.LIST or a1 == UTIL_PPC.ITEM or a1 == UTIL_PPC.FILTER then
        if UTIL_PPC.co == nil then
          funcLuaMenuCommand(711242136, a1, a2, false)
        end
        return
      end
      return prev(a1, a2, ...)
    end
  end)
end
